mapper.select:
SELECT COUNT(*)
FROM ORDERS
WHERE IDEMPOTENCY_KEY = #{idempotencyKey}

mapper.update:
UPDATE ORDERS
SET ORDER_STATUS = #{orderStatus},
    ERROR_MESSAGE = #{errorMessage},
    UPDATED_AT = #{updatedAt}
WHERE ID = #{orderId}
  AND ORDER_STATUS IN ('ORDERING', 'REQUESTED', 'DRY_RUN', 'ACCEPTED', 'PARTIALLY_FILLED', 'RETRY_PENDING')

UPDATE ORDERS
SET BROKER_STATUS = #{brokerStatus},
    ERROR_MESSAGE = #{errorMessage},
    UPDATED_AT = #{updatedAt}
WHERE ID = #{orderId}
  AND ORDER_STATUS IN ('ACCEPTED', 'PARTIALLY_FILLED')

UPDATE DOMESTIC_STOCK_MASTER
SET LAST_SELECTED_AT = #{selectedAt},
    UPDATED_AT = #{selectedAt}
WHERE ID = #{id}

UPDATE DOMESTIC_STOCK_MASTER
SET LAST_BUY_ATTEMPT_AT = #{attemptedAt},
    UPDATED_AT = #{attemptedAt}
WHERE SYMBOL = #{symbol}
  AND MARKET_CODE = #{marketCode}

UPDATE DOMESTIC_STOCK_MASTER
SET CONSECUTIVE_FAILURES = CONSECUTIVE_FAILURES + 1,
    RETRY_AFTER = #{retryAfter},
    EXCLUDED_REASON = #{reason},
    UPDATED_AT = #{updatedAt}
WHERE SYMBOL = #{symbol}
  AND MARKET_CODE = #{marketCode}

UPDATE DOMESTIC_STOCK_MASTER
SET LAST_BUY_SUCCESS_AT = #{successAt},
    CONSECUTIVE_FAILURES = 0,
    RETRY_AFTER = NULL,
    EXCLUDED_REASON = NULL,
    UPDATED_AT = #{successAt}
WHERE SYMBOL = #{symbol}
  AND MARKET_CODE = #{marketCode}

mapper.select:
SELECT COUNT(*)
FROM OVERSEAS_STOCK_MASTER
WHERE EXCHANGE_CODE = #{exchangeCode}
  AND CURRENCY_CODE = #{currencyCode}

SELECT COUNT(*)
FROM OVERSEAS_STOCK_MASTER
WHERE EXCHANGE_CODE = #{exchangeCode}
  AND PRICE_EXCHANGE_CODE = #{priceExchangeCode}
  AND CURRENCY_CODE = #{currencyCode}
  AND ACTIVE = 'Y'
  AND TRADABLE = 'Y'
  AND FRACTIONAL_TRADABLE = 'YES'

mapper.update:
UPDATE OVERSEAS_STOCK_MASTER
SET LAST_SELECTED_AT = #{selectedAt},
    UPDATED_AT = #{selectedAt}
WHERE ID = #{id}

UPDATE OVERSEAS_STOCK_MASTER
SET LAST_BUY_ATTEMPT_AT = #{attemptedAt},
    UPDATED_AT = #{attemptedAt}
WHERE SYMBOL = #{symbol}
  AND EXCHANGE_CODE = #{exchangeCode}

UPDATE OVERSEAS_STOCK_MASTER
SET CONSECUTIVE_FAILURES = CONSECUTIVE_FAILURES + 1,
    RETRY_AFTER = #{retryAfter},
    EXCLUDED_REASON = #{reason},
    UPDATED_AT = #{updatedAt}
WHERE SYMBOL = #{symbol}
  AND EXCHANGE_CODE = #{exchangeCode}

UPDATE OVERSEAS_STOCK_MASTER
SET LAST_BUY_SUCCESS_AT = #{successAt},
    CONSECUTIVE_FAILURES = 0,
    RETRY_AFTER = NULL,
    EXCLUDED_REASON = NULL,
    UPDATED_AT = #{successAt}
WHERE SYMBOL = #{symbol}
  AND EXCHANGE_CODE = #{exchangeCode}

UPDATE OVERSEAS_STOCK_MASTER
SET LAST_VERIFICATION_ATTEMPT_AT = #{attemptedAt},
    VERIFICATION_ATTEMPT_COUNT = COALESCE(VERIFICATION_ATTEMPT_COUNT, 0) + 1,
    UPDATED_AT = #{attemptedAt}
WHERE SYMBOL = #{symbol}
  AND EXCHANGE_CODE = #{exchangeCode}

UPDATE OVERSEAS_STOCK_MASTER
SET FRACTIONAL_TRADABLE = 'UNKNOWN',
    LAST_KIS_RESPONSE_CODE = #{responseCode},
    LAST_KIS_RESPONSE_MESSAGE = #{responseMessage},
    RETRY_AFTER = #{retryAfter},
    EXCLUDED_REASON = #{responseMessage},
    UPDATED_AT = #{updatedAt}
WHERE SYMBOL = #{symbol}
  AND EXCHANGE_CODE = #{exchangeCode}
  AND FRACTIONAL_TRADABLE = 'UNKNOWN'
